solution.code:
#include <stdio.h>

int digit_sum(int n) {
    if (n == 0) {
        return 0;
    }
    return n % 10 + digit_sum(n / 10);
}

int main() {
    printf("%d\n", digit_sum(5139));
    return 0;
}
